struct print
{
    HANDLE printer;
    WCHAR *output;
    enum print_flags flags;
    DEVMODEW *devmode;
};

enum print_flags
{
    CALL_START_PAGE = 0x1,
    CALL_END_PAGE   = 0x2,
    WRITE_DEVMODE   = 0x4,
    BANDING         = 0x8,
};
